input.command:
python3 - <<'PY'
from pathlib import Path
Path('src/money.ts').write_text("""export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
""")
for module, old in [('invoice', 'invoiceAmount'), ('report', 'reportAmount')]:
    p = Path(f'src/{module}.ts')
    p.write_text(p.read_text().replace(old, 'formatAmount').replace("from './formatAmount'", "from './money'"))
    Path(f'src/{old}.ts').unlink()
Path('checks/public.cjs').write_text("""const assert = require('node:assert/strict');
const { formatAmount } = require('../.build/money');
const { renderInvoice } = require('../.build/invoice');
const { renderReport } = require('../.build/report');

const cases = [
  [0, '0.00'],
  [-0, '0.00'],
  [1, '0.01'],
  [9, '0.09'],
  [99, '0.99'],
  [100, '1.00'],
  [123, '1.23'],
  [123456, '1234.56'],
  [-1, '-0.01'],
  [-9, '-0.09'],
  [-99, '-0.99'],
  [-100, '-1.00'],
  [-123, '-1.23'],
  [-123456, '-1234.56'],
];

for (const [cents, expected] of cases) {
  assert.equal(formatAmount(cents), expected);
  assert.equal(renderInvoice('inv', cents), 'inv: $' + expected);
}

assert.equal(renderReport([]), '');
assert.equal(
  renderReport(cases.map(([cents], index) => ({ id: String(index), cents }))),
  cases.map(([, expected], index) => index + ',' + expected).join('\\n'),
);
assert.equal(renderReport([{ id: 'a', cents: 0 }, { id: 'b', cents: -1 }]), 'a,0.00\\nb,-0.01');
""")
PY
tsc -p tsconfig.json && node checks/public.cjs
find src -type f -maxdepth 1 -print; grep -R -nE 'invoiceAmount|reportAmount' src || true

